#include "TemplateEngine.hpp"
namespace exotic { std::string TemplateEngine::Header(const std::string& name){ return "#pragma once\n#include ^<string^>\n\nnamespace exotic {\n\nclass "+name+" {\npublic:\n    "+name+"^(^)^;\n    void Initialize^(^)^;\n    void Update^(^)^;\n};\n\n}\n"; } std::string TemplateEngine::Source(const std::string& name){ return "#include \"../../include/"+name+".hpp\"\n#include ^<iostream^>\n\nnamespace exotic {\n\n"+name+"::"+name+"^(^) {}\nvoid "+name+"::Initialize^(^){ std::cout ^<^< \""+name+" initialized.\" ^<^< std::endl; }\nvoid "+name+"::Update^(^){ std::cout ^<^< \""+name+" updated.\" ^<^< std::endl; }\n\n}\n"; } }
